# Which NIST SP 800-34 plans does a disruption activate? (simplified routing)
def plans_for(event):
    plans = []
    if event["people_in_danger"]:
        plans.append("OEP (occupant emergency)")
    if event["malicious"]:
        plans.append("Cyber incident response plan")
    if event["site_unusable"]:
        plans.append("DRP (move systems to alternate site)")
    if event["systems_down"]:
        plans.append("ISCP (recover each system)")
    if event["business_process_stopped"]:
        plans.append("BCP (keep the process running)")
    if event["public_or_customer_impact"]:
        plans.append("Crisis communications plan")
    return plans

fire = dict(people_in_danger=True, malicious=False, site_unusable=True,
            systems_down=True, business_process_stopped=True,
            public_or_customer_impact=True)
bad_delete = dict(people_in_danger=False, malicious=False, site_unusable=False,
                  systems_down=True, business_process_stopped=True,
                  public_or_customer_impact=True)
for name, ev in [("data-centre fire", fire), ("wrong-host delete", bad_delete)]:
    print(name, "->", "; ".join(plans_for(ev)))

import time
store = {"site-17": {"type": "site", "deleted_at": None},
         "app-9":   {"type": "app",  "deleted_at": None, "site": "site-17"}}

def delete_unsafe(ids):                 # accepts any id, deletes for good
    for i in ids:
        store.pop(i)

def delete_apps(ids, dry_run=True, max_items=50):
    """Typed, previewed, bounded and reversible."""
    wrong = [i for i in ids if store[i]["type"] != "app"]
    if wrong:
        raise ValueError(f"not app ids: {wrong}")
    if len(ids) > max_items:
        raise ValueError("batch too large, needs a second approver")
    if dry_run:
        return f"would soft-delete {len(ids)} app(s)"
    for i in ids:
        store[i]["deleted_at"] = time.time()   # purge only after retention
    return f"soft-deleted {len(ids)} app(s)"

try:
    delete_apps(["site-17"])             # the Atlassian-style mix-up
except ValueError as e:
    print("refused:", e)
print(delete_apps(["app-9"]))
print(delete_apps(["app-9"], dry_run=False))
print("site still there:", "site-17" in store)
